    explain: "### The backbone of jazz harmony\nRoots moving by 4ths through the key (I IV vii iii vi ii V I) is the progression behind *Autumn Leaves*, *Fly Me to the Moon* and countless others. Learn it as voice-led drop 2s and you have the skeleton of half the standards.\n\n### Voice-leading rule\nGoing up a 4th, **7 → 3** (the 7th falls a half or whole step to the next chord's 3rd) and **3 → 7** (the 3rd holds and becomes the next 7th). Keep those guide tones moving by step and the rest follows.",
