    explain: "### Coltrane changes\nJohn Coltrane's 1959 innovation (*Giant Steps*, *Countdown*) divides the octave into **three equal major thirds** and visits each tonic via its V7. Romans relative to the home key: **I – bIII7 – bVI – VII7 – III – V7 – I**. Practise it slowly: the challenge is hearing three keys in eight beats.",
    visual: { type: "progression", key: "$key", chart: "| I:maj7 bIII:7 | bVI:maj7 VII:7 | III:maj7 V:7 | I:maj7 |", voiceLead: true, voicing: "drop2", stringSet: [4, 3, 2, 1] },
