    prompt: "Take **| ii7 | V7 | Imaj7 | % |** in **{key}** and approach every chord from **a half step above, same quality**, on the last two beats of the previous bar: **| biii7 ii7 | bVI7 V7 | bIImaj7 Imaj7 | % |**.",
