    params: { key: "major" },
    prompt: "Play **| ii7 V7 | Imaj7 |** then **| iv7 bVII7 | Imaj7 |** in **{key}**. Then try **| IVmaj7 | iv7 bVII7 | Imaj7 | % |**. Find voicings where only one or two notes change.",
