    explain: "### Where borrowed chords come from (in C major)\n| Source mode (on C) | Chords you can borrow |\n|---|---|\n| Aeolian (natural minor) | i m7, iiø7, **bIIImaj7, iv7, v7, bVImaj7, bVII7** |\n| Dorian | **IV7**, bVIImaj7, i m6 |\n| Phrygian | **bIImaj7**, bIII7, **bvii7** |\n| Mixolydian | **bVIImaj7/bVII**, v7, I7 |\n| Lydian | **II7**, #ivø7, vii7 |\n| Harmonic minor | i(maj7), iiø7, bIIImaj7#5, iv7, V7b9, bVImaj7, **vii°7** |\n| Melodic minor | i(maj7), ii7, **IV7**, V7, viø7 |\n| Harmonic major | iiø7, **iv(maj7)/iv6**, bVImaj7#5, vii°7 |\n| Locrian | **bVmaj7**, bVI7, biii7 |\n\nThe workhorses are **iv, bVII7, bVI, bIII, iiø7** (Aeolian) and **bIImaj7** (Phrygian).",
