    visual: { type: "progression", key: "$key", chart: "| i:mMaj7 | % | v:m7 | I:7 | IV:maj7 | % | iv:m7 | bVII:7 | bIII:maj7 | biii:m7 bVI:7 | bII:maj7 | ii:m7b5 V:7 |", voiceLead: true },
