    explain: "### The core skill\nChord melody is mostly one question asked over and over: **which chord has this melody note on top?** Every diatonic note fits three diatonic triads, and more 7th chords. Harmonizing a scale both ways (one chord per note, then alternatives) trains that question. Ted Greene's chord-scale studies are this idea taken to the limit.",
    visual: { type: "chordMelody", key: "$key", scale: "major", melody: "1 2 3 4 | 5 6 7 1' |", chart: "| I:maj V:maj vi:min ii:min | I:maj IV:maj V:7 I:maj |", style: "triad-top" },
