      { type: "chordMelody", key: "$key", scale: "major", melody: "1 2 3 4 | 5 6 7 1' |", chart: "| I:maj7 V:7 vi:m7 ii:m7 | I:maj7 IV:maj7 V:7 I:maj7 |", style: "drop2-top", title: "Another way: drop 2 sevenths" },
      { type: "chordMelody", key: "$key", scale: "major", melody: "1 2 3 4 | 5 6 7 1' |", chart: "| vi:m7 ii:m7 I:maj7 V:7sus4 | iii:m7 ii:m7 iii:m7 IV:maj7 |", style: "drop2-top", title: "A third way: different chords for each note" }
