    explain: "### Why drones?\nA drone fixes the tonic so the ear hears **scale degrees**, not just notes. That's how a mode stops being 'the major scale starting somewhere else' and becomes its own sound. Indian classical musicians practise this way for years; jazz players use it to internalize modes and chord-scales.",
