    explain: "### Minor modes by colour\n| Mode | Formula | Colour note | Sound |\n|---|---|---|---|\n| Dorian | 1 2 b3 4 5 6 b7 | **6** | minor but bright (Santana, *So What*) |\n| Aeolian | 1 2 b3 4 5 b6 b7 | **b6** | sad, rock/pop minor |\n| Phrygian | 1 b2 b3 4 5 b6 b7 | **b2** | Spanish, metal |\n| Locrian | 1 b2 b3 4 b5 b6 b7 | **b5** | unstable; mostly used over m7b5 chords |",
    visual: { type: "scale", root: "$root", scale: "$scale", region: { caged: "$caged" } },
