    mode: "play", category: "improv", tags: ["targeting", "chord-tones", "ii-v-i"],
    title: "Land on the 3rd: ii–V–I in {key}",
    level: 3, length: "short", minutes: 3,
    params: { key: "major" },
    prompt: "Improvise over **| ii7 | V7 | Imaj7 | % |** in **{key}**. Rule: **beat 1 of every bar must be the 3rd** of that bar's chord. Anything goes in between.",
