    prompt: "Over the cycle **iv7 bVII7 bIIImaj7 bVImaj7 iiø7 V7 im6** in **{key}**, play a **guide-tone line**: one note per bar, alternating 3rd and 7th, each moving by half or whole step. Then embellish it into an 8th-note line that still hits those notes on beat 1.",
    goal: "A singable whole-note line, then a full solo built around it.",
