    visual: { type: "progression", key: "$key", chart: "| I:7 | IV:7 | I:7 | v:m7 I:7 | IV:7 | #iv:dim7 | I:7 | iii:m7 VI:7 | ii:m7 | V:7 | I:7 VI:7 | ii:m7 V:7 |", walk: "arpeggio" },
