    explain: "### Playing the sub without the band\nYou don't need the rhythm section to play bII7: superimposing its arpeggio over V7 gives **b5, b7, b9 and 3** of V, an instant altered sound. That equivalence (**bII Lydian dominant = V altered**) is one of the most useful in jazz.",
