    explain: "### Side-slipping\nPlaying a phrase a half step away from the key and then resolving it is the simplest 'outside' device. John Scofield, Michael Brecker and the post-Coltrane players use it constantly: tension comes from the contrast, resolution from the half-step return. Rule: **go out briefly, come back by half step, phrase strongly**.",
