    demo: { type: "progression", key: "$key", chart: "| i:m7 | bii:m7 | i:m7 | % |", walk: "arpeggio", scales: { "i:m7": "minor-pentatonic", "bii:m7": "minor-pentatonic" } },
    concepts: ["sidestepping"],
