    prompt: "While the rhythm section plays **| ii7 | V7 | Imaj7 | % |** in **{key}**, solo on the Coltrane substitution **ii7 bIII7 | bVImaj7 VII7 | IIImaj7 V7 | Imaj7**: 1-2-3-5 cells on each chord.",
    goal: "Your lines imply the three key centres and still land on I.",
