    explain: "### Forward motion\nHal Galper's *Forward Motion* argues that jazz lines are heard **toward** strong beats: the important note is the one you arrive on, and everything before it is a pickup. Practising this way fixes the most common intermediate habit: phrases that start on beat 1 and wander.",
    visual: { type: "progression", key: "$key", chart: "| ii:m7 V:7 | I:maj7 | ii:m7 V:7 | I:maj7 |", walk: "arpeggio" },
