    hints: [
      "Over G7alt: Db major (Db F Ab = #11 b7 b9) and Eb major (Eb G Bb = b13 1 #9).",
      "Both triads live in Ab melodic minor (= G altered): they're its IV and V triads.",
      "Six notes, no scale steps: wide intervals give the modern 'triad pair' sound."
    ],
    explain: "### Triad pairs\nTwo triads with no common tones give a 6-note collection that sounds fresh because it moves in leaps. Taken from the IV and V of the parent melodic minor, they cover nearly the whole altered scale. Jerry Bergonzi's *Hexatonics* and Gary Campbell's *Triad Pairs for Jazz* document the approach.",
    visual: { type: "fretboard", root: "$root", tones: ["#11", "b7", "b9", "b13", "1", "#9"], region: { frets: [0, 15] }, title: "bV + bVI triads over the dominant" },
